-- Separate operational journal; no IF NOT EXISTS, reset or deletion path.
CREATE TABLE d1_cveharbor_repair_receipts(id TEXT PRIMARY KEY CHECK(id IN('install-intent','install-started','installed','resume-intent','resume-started')),payload TEXT NOT NULL CHECK(json_valid(payload)),recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER d1_cveharbor_repair_receipts_immutable_update BEFORE UPDATE ON d1_cveharbor_repair_receipts BEGIN SELECT RAISE(ABORT,'Repair receipts are immutable'); END;
CREATE TRIGGER d1_cveharbor_repair_receipts_immutable_delete BEFORE DELETE ON d1_cveharbor_repair_receipts BEGIN SELECT RAISE(ABORT,'Repair receipts are immutable'); END;
CREATE TRIGGER d1_cveharbor_repair_receipts_sequence BEFORE INSERT ON d1_cveharbor_repair_receipts BEGIN
 SELECT CASE WHEN NOT (
 (NEW.id='install-intent' AND (SELECT COUNT(*) FROM d1_cveharbor_repair_receipts)=0) OR
 (NEW.id='install-started' AND (SELECT COUNT(*) FROM d1_cveharbor_repair_receipts)=1 AND NEW.payload=(SELECT payload FROM d1_cveharbor_repair_receipts WHERE id='install-intent')) OR
 (NEW.id='installed' AND (SELECT COUNT(*) FROM d1_cveharbor_repair_receipts)=2 AND NEW.payload=(SELECT payload FROM d1_cveharbor_repair_receipts WHERE id='install-started')) OR
 (NEW.id='resume-intent' AND (SELECT COUNT(*) FROM d1_cveharbor_repair_receipts)=3 AND EXISTS(SELECT 1 FROM d1_cveharbor_repair_receipts WHERE id='installed')) OR
 (NEW.id='resume-started' AND (SELECT COUNT(*) FROM d1_cveharbor_repair_receipts)=4 AND NEW.payload=(SELECT payload FROM d1_cveharbor_repair_receipts WHERE id='resume-intent'))
 ) THEN RAISE(ABORT,'Repair sequence or receipt mismatch') END;
 SELECT CASE WHEN NEW.id IN('install-intent','install-started','resume-intent','resume-started') AND NOT COALESCE((
 CASE
 WHEN json_type(NEW.payload,'$.version') IS NOT 'integer' THEN 0
 WHEN EXISTS(SELECT 1 FROM json_each(NEW.payload) WHERE key IN('version','not_before','expires_at') GROUP BY key HAVING COUNT(*)>1) THEN 0
 WHEN json_extract(NEW.payload,'$.version')=1 THEN (
  json_type(NEW.payload,'$.not_before')='integer' AND json_type(NEW.payload,'$.expires_at')='integer'
  AND json_extract(NEW.payload,'$.expires_at') - json_extract(NEW.payload,'$.not_before') BETWEEN 0 AND 1800
  AND CAST(strftime('%s','now') AS INTEGER) BETWEEN json_extract(NEW.payload,'$.not_before') AND json_extract(NEW.payload,'$.expires_at')
 )
 WHEN json_extract(NEW.payload,'$.version')=2 THEN (
  ((NEW.id IN('install-intent','install-started') AND json_extract(NEW.payload,'$.operation')='install') OR (NEW.id IN('resume-intent','resume-started') AND (((json_extract(NEW.payload,'$.operation')='resume' AND json_extract(NEW.payload,'$.account')='aa99b9b15e0492302e4f6484b8d27bc2') AND (json_extract(NEW.payload,'$.run_id')!=(SELECT json_extract(payload,'$.run_id') FROM d1_cveharbor_repair_receipts WHERE id='installed') AND (json_extract(NEW.payload,'$.approval_id')!=(SELECT json_extract(payload,'$.approval_id') FROM d1_cveharbor_repair_receipts WHERE id='installed') AND json_type(NEW.payload,'$.expected_revision')='integer' AND json_extract(NEW.payload,'$.expected_revision')=0))) AND ((json_type(NEW.payload,'$.resume_scheduled_work_and_eligible_email')='true' AND (json_type(NEW.payload,'$.install_receipt_sha256')='text' AND length(json_extract(NEW.payload,'$.install_receipt_sha256'))=64 AND json_extract(NEW.payload,'$.install_receipt_sha256') NOT GLOB '*[^0-9a-f]*')) AND ((json_type(NEW.payload,'$.verification_sha256')='text' AND length(json_extract(NEW.payload,'$.verification_sha256'))=64 AND json_extract(NEW.payload,'$.verification_sha256') NOT GLOB '*[^0-9a-f]*') AND ((json_type(NEW.payload,'$.sql_sha256')='text' AND length(json_extract(NEW.payload,'$.sql_sha256'))=64 AND json_extract(NEW.payload,'$.sql_sha256') NOT GLOB '*[^0-9a-f]*') AND json_extract(NEW.payload,'$.verification_sha256')=json_extract(NEW.payload,'$.preflight_sha256')))))))
  AND json_type(NEW.payload,'$.not_before') IS NULL AND json_type(NEW.payload,'$.expires_at') IS NULL
  AND json_type(NEW.payload,'$.run_id')='text' AND length(json_extract(NEW.payload,'$.run_id'))>0 AND json_extract(NEW.payload,'$.run_id') NOT GLOB '*[^0-9]*'
  AND json_type(NEW.payload,'$.source_sha')='text' AND length(json_extract(NEW.payload,'$.source_sha'))=40 AND json_extract(NEW.payload,'$.source_sha') NOT GLOB '*[^0-9a-f]*'
  AND json_extract(NEW.payload,'$.database')='46710e51-7ca4-4571-b89c-921b9969de0b'
 ) ELSE 0 END AND
 ((((((json_array_length(json_extract(NEW.payload,'$.schema_rows'))=(SELECT COUNT(*) FROM (SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' AND name NOT GLOB '_cf_*' AND name NOT GLOB 'd1_*' ORDER BY type,name)) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.payload,'$.schema_rows') e WHERE NOT EXISTS(SELECT 1 FROM sqlite_schema s WHERE s.type=json_extract(e.value,'$.type') AND s.name=json_extract(e.value,'$.name') AND s.tbl_name=json_extract(e.value,'$.tbl_name') AND s.sql=json_extract(e.value,'$.sql'))) AND (SELECT COUNT(*) FROM "alert_delivery_items")=json_extract(NEW.payload,'$.counts.alert_delivery_items')) AND ((SELECT COUNT(*) FROM "alert_digest_runs")=json_extract(NEW.payload,'$.counts.alert_digest_runs') AND (SELECT COUNT(*) FROM "alert_optins")=json_extract(NEW.payload,'$.counts.alert_optins'))) AND (((SELECT COUNT(*) FROM "alert_preferences")=json_extract(NEW.payload,'$.counts.alert_preferences') AND (SELECT COUNT(*) FROM "auth_rate_limits")=json_extract(NEW.payload,'$.counts.auth_rate_limits')) AND ((SELECT COUNT(*) FROM "customer_finding_statuses")=json_extract(NEW.payload,'$.counts.customer_finding_statuses') AND ((SELECT COUNT(*) FROM "customer_finding_ticket_history")=json_extract(NEW.payload,'$.counts.customer_finding_ticket_history') AND (SELECT COUNT(*) FROM "customer_finding_tickets")=json_extract(NEW.payload,'$.counts.customer_finding_tickets'))))) AND ((((SELECT COUNT(*) FROM "customer_security_score_snapshots")=json_extract(NEW.payload,'$.counts.customer_security_score_snapshots') AND (SELECT COUNT(*) FROM "cvie_advisories")=json_extract(NEW.payload,'$.counts.cvie_advisories')) AND ((SELECT COUNT(*) FROM "cvie_disclosure_products")=json_extract(NEW.payload,'$.counts.cvie_disclosure_products') AND (SELECT COUNT(*) FROM "cvie_disclosure_queue")=json_extract(NEW.payload,'$.counts.cvie_disclosure_queue'))) AND (((SELECT COUNT(*) FROM "cvie_disclosures")=json_extract(NEW.payload,'$.counts.cvie_disclosures') AND (SELECT COUNT(*) FROM "cvie_kev")=json_extract(NEW.payload,'$.counts.cvie_kev')) AND ((SELECT COUNT(*) FROM "cvie_maintenance")=json_extract(NEW.payload,'$.counts.cvie_maintenance') AND ((SELECT COUNT(*) FROM "cvie_product_scopes")=json_extract(NEW.payload,'$.counts.cvie_product_scopes') AND (SELECT COUNT(*) FROM "cvie_products")=json_extract(NEW.payload,'$.counts.cvie_products')))))) AND (((((SELECT COUNT(*) FROM "cvie_provider_budget")=json_extract(NEW.payload,'$.counts.cvie_provider_budget') AND (SELECT COUNT(*) FROM "cvie_shared_advisories")=json_extract(NEW.payload,'$.counts.cvie_shared_advisories')) AND ((SELECT COUNT(*) FROM "cvie_shared_scopes")=json_extract(NEW.payload,'$.counts.cvie_shared_scopes') AND (SELECT COUNT(*) FROM "cvie_shared_seeds")=json_extract(NEW.payload,'$.counts.cvie_shared_seeds'))) AND (((SELECT COUNT(*) FROM "cvie_sources")=json_extract(NEW.payload,'$.counts.cvie_sources') AND (SELECT COUNT(*) FROM "cvie_subscriptions")=json_extract(NEW.payload,'$.counts.cvie_subscriptions')) AND ((SELECT COUNT(*) FROM "inventory_assets")=json_extract(NEW.payload,'$.counts.inventory_assets') AND ((SELECT COUNT(*) FROM "inventory_customers")=json_extract(NEW.payload,'$.counts.inventory_customers') AND (SELECT COUNT(*) FROM "inventory_environments")=json_extract(NEW.payload,'$.counts.inventory_environments'))))) AND ((((SELECT COUNT(*) FROM "inventory_packages")=json_extract(NEW.payload,'$.counts.inventory_packages') AND (SELECT COUNT(*) FROM "inventory_software_history")=json_extract(NEW.payload,'$.counts.inventory_software_history')) AND ((SELECT COUNT(*) FROM "lifecycle_delivery")=json_extract(NEW.payload,'$.counts.lifecycle_delivery') AND (SELECT COUNT(*) FROM "lifecycle_preferences")=json_extract(NEW.payload,'$.counts.lifecycle_preferences'))) AND (((SELECT COUNT(*) FROM "lifecycle_watches")=json_extract(NEW.payload,'$.counts.lifecycle_watches') AND (SELECT COUNT(*) FROM "login_challenges")=json_extract(NEW.payload,'$.counts.login_challenges')) AND ((SELECT COUNT(*) FROM "plugin_installation_status")=json_extract(NEW.payload,'$.counts.plugin_installation_status') AND ((SELECT COUNT(*) FROM "plugin_monitor_checks")=json_extract(NEW.payload,'$.counts.plugin_monitor_checks') AND (SELECT COUNT(*) FROM "plugin_monitor_history")=json_extract(NEW.payload,'$.counts.plugin_monitor_history'))))))) AND ((((((SELECT COUNT(*) FROM "plugin_release_checks")=json_extract(NEW.payload,'$.counts.plugin_release_checks') AND (SELECT COUNT(*) FROM "plugin_source_mappings")=json_extract(NEW.payload,'$.counts.plugin_source_mappings')) AND ((SELECT COUNT(*) FROM "remediation_assignment_events")=json_extract(NEW.payload,'$.counts.remediation_assignment_events') AND (SELECT COUNT(*) FROM "remediation_assignment_fyi")=json_extract(NEW.payload,'$.counts.remediation_assignment_fyi'))) AND (((SELECT COUNT(*) FROM "remediation_assignment_limits")=json_extract(NEW.payload,'$.counts.remediation_assignment_limits') AND (SELECT COUNT(*) FROM "remediation_assignment_metadata")=json_extract(NEW.payload,'$.counts.remediation_assignment_metadata')) AND ((SELECT COUNT(*) FROM "remediation_assignment_notifications")=json_extract(NEW.payload,'$.counts.remediation_assignment_notifications') AND ((SELECT COUNT(*) FROM "remediation_assignment_requests")=json_extract(NEW.payload,'$.counts.remediation_assignment_requests') AND (SELECT COUNT(*) FROM "remediation_assignments")=json_extract(NEW.payload,'$.counts.remediation_assignments'))))) AND ((((SELECT COUNT(*) FROM "remediation_change_context")=json_extract(NEW.payload,'$.counts.remediation_change_context') AND (SELECT COUNT(*) FROM "remediation_finding_links")=json_extract(NEW.payload,'$.counts.remediation_finding_links')) AND ((SELECT COUNT(*) FROM "remediation_link_audit")=json_extract(NEW.payload,'$.counts.remediation_link_audit') AND (SELECT COUNT(*) FROM "remediation_owner_comments")=json_extract(NEW.payload,'$.counts.remediation_owner_comments'))) AND (((SELECT COUNT(*) FROM "remediation_record_metadata")=json_extract(NEW.payload,'$.counts.remediation_record_metadata') AND (SELECT COUNT(*) FROM "remediation_retired_records")=json_extract(NEW.payload,'$.counts.remediation_retired_records')) AND ((SELECT COUNT(*) FROM "remediation_review_access")=json_extract(NEW.payload,'$.counts.remediation_review_access') AND ((SELECT COUNT(*) FROM "remediation_review_activity")=json_extract(NEW.payload,'$.counts.remediation_review_activity') AND (SELECT COUNT(*) FROM "remediation_review_challenges")=json_extract(NEW.payload,'$.counts.remediation_review_challenges')))))) AND (((((SELECT COUNT(*) FROM "remediation_review_notifications")=json_extract(NEW.payload,'$.counts.remediation_review_notifications') AND (SELECT COUNT(*) FROM "remediation_review_sessions")=json_extract(NEW.payload,'$.counts.remediation_review_sessions')) AND ((SELECT COUNT(*) FROM "remediation_review_write_context")=json_extract(NEW.payload,'$.counts.remediation_review_write_context') AND (SELECT COUNT(*) FROM "remediation_status_changes")=json_extract(NEW.payload,'$.counts.remediation_status_changes'))) AND (((SELECT COUNT(*) FROM "remediation_status_notifications")=json_extract(NEW.payload,'$.counts.remediation_status_notifications') AND (SELECT COUNT(*) FROM "remediations")=json_extract(NEW.payload,'$.counts.remediations')) AND ((SELECT COUNT(*) FROM "sessions")=json_extract(NEW.payload,'$.counts.sessions') AND ((SELECT COUNT(*) FROM "totp_login_challenges")=json_extract(NEW.payload,'$.counts.totp_login_challenges') AND (SELECT COUNT(*) FROM "totp_recovery_codes")=json_extract(NEW.payload,'$.counts.totp_recovery_codes'))))) AND ((((SELECT COUNT(*) FROM "user_stack")=json_extract(NEW.payload,'$.counts.user_stack') AND (SELECT COUNT(*) FROM "user_technology_catalogue")=json_extract(NEW.payload,'$.counts.user_technology_catalogue')) AND ((SELECT COUNT(*) FROM "user_totp")=json_extract(NEW.payload,'$.counts.user_totp') AND (SELECT COUNT(*) FROM "users")=json_extract(NEW.payload,'$.counts.users'))) AND (((SELECT COUNT(*) FROM "web_risk_account_usage")=json_extract(NEW.payload,'$.counts.web_risk_account_usage') AND (SELECT COUNT(*) FROM "web_risk_usage")=json_extract(NEW.payload,'$.counts.web_risk_usage')) AND ((SELECT COUNT(*) FROM "website_monitor_checks")=json_extract(NEW.payload,'$.counts.website_monitor_checks') AND ((SELECT COUNT(*) FROM "website_monitors")=json_extract(NEW.payload,'$.counts.website_monitors') AND ((((SELECT COUNT(*) n FROM (SELECT user_id,asset_id,cve_id FROM remediation_finding_links GROUP BY user_id,asset_id,cve_id HAVING COUNT(*)>1))=0 AND (SELECT COUNT(*) n FROM remediation_finding_links l LEFT JOIN remediations r ON r.user_id=l.user_id AND r.cve_id=l.record_id LEFT JOIN inventory_assets a ON a.user_id=l.user_id AND a.id=l.asset_id LEFT JOIN inventory_environments e ON e.user_id=a.user_id AND e.id=a.environment_id LEFT JOIN inventory_customers c ON c.user_id=e.user_id AND c.id=e.customer_id WHERE r.cve_id IS NULL OR c.id IS NULL OR l.record_id NOT IN(l.cve_id,l.cve_id||'~'||upper(l.asset_id)) OR l.asset_id!=lower(l.asset_id) OR l.cve_id!=upper(l.cve_id))=0) AND ((SELECT COUNT(*) n FROM remediation_finding_links l JOIN remediations r ON r.user_id=l.user_id AND r.cve_id=l.record_id LEFT JOIN customer_finding_statuses s ON s.user_id=l.user_id AND s.asset_id=l.asset_id AND s.cve_id=l.cve_id WHERE COALESCE(s.status,'Needs Review')!=CASE r.status WHEN 'Open' THEN 'Needs Review' WHEN 'Investigating' THEN 'Fix in Progress' WHEN 'Remediated' THEN 'Fixed/Patched' ELSE r.status END)=0 AND (SELECT COUNT(*) n FROM remediations r WHERE instr(r.cve_id,'~')>0 AND NOT EXISTS(SELECT 1 FROM remediation_finding_links l WHERE l.user_id=r.user_id AND l.record_id=r.cve_id) AND NOT EXISTS(SELECT 1 FROM remediation_retired_records t WHERE t.user_id=r.user_id AND t.record_id=r.cve_id))=0)) AND (((SELECT COUNT(*) n FROM remediation_retired_records t LEFT JOIN remediations r ON r.user_id=t.user_id AND r.cve_id=t.canonical_id WHERE r.cve_id IS NULL OR EXISTS(SELECT 1 FROM remediation_finding_links l WHERE l.user_id=t.user_id AND l.record_id=t.record_id) OR EXISTS(SELECT 1 FROM remediation_retired_records x WHERE x.user_id=t.user_id AND x.record_id=t.canonical_id))=0 AND (SELECT COUNT(*) n FROM remediation_status_changes s LEFT JOIN remediations r ON r.user_id=s.user_id AND r.cve_id=s.cve_id WHERE r.cve_id IS NULL)=0) AND ((SELECT COUNT(*) n FROM remediation_assignment_requests a LEFT JOIN remediations r ON r.user_id=a.user_id AND r.cve_id=a.cve_id WHERE r.cve_id IS NULL)=0 AND ((SELECT COUNT(*) n FROM remediation_status_notifications n LEFT JOIN remediation_status_changes s ON s.id=n.change_id WHERE s.id IS NULL)=0 AND (SELECT COUNT(*) n FROM pragma_foreign_key_check)=0)))))))))))
 ),0) THEN RAISE(ABORT,'Repair approval expired or database drifted') END;
END;
